// === Tab: mySketch ===
// じゅーりあー
// ???

const SIZE = 1112;
const SIZE2 = 834;

let myShader;
let vs =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"void main(void){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

let fs =
"precision mediump float;" +
"uniform vec2 u_resolution;" +
"uniform float u_count;" +
"uniform vec2 u_mouse;" +
"const int limit = 64;" +
"const float pi = 3.14159;" +
"const float bound = 64.0;" +
// hsbで書かれた(0.0～1.0)の数値vec3をrgbに変換する魔法のコード
"vec3 getRGB(float h, float s, float b){" +
"  vec3 c = vec3(h, s, b);" +
"  vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);" +
"  rgb = rgb * rgb * (3.0 - 2.0 * rgb);" +
"  return c.z * mix(vec3(1.0), rgb, c.y);" +
"}" +
"vec3 getJS(in vec2 p){" +
// pの位置に応じて64回の計算を行なう
// 64回やっても±2を出なければ合格とする
// 出てしまった場合にその時の回数を使って色付けする感じ
// 綺麗な青から黒へ向かわせる（64で黒）
"  float h = 1.0;" +
"  float mx = (u_mouse.x * 2.0 - u_resolution.x) / u_resolution.x;" +
"  float my = (u_mouse.y * 2.0 - u_resolution.y) / u_resolution.y;" +
"  mx = -0.15 + 0.6 * cos(u_count * pi / 480.0);" +
"  my = 0.75 * sin(u_count * pi / 480.0);" +
"  vec2 q = vec2(mx, my);" +
"  vec2 r;" +
"  bool outFlag = false;" +
"  for(int i = 0; i < limit; i++){" +
"    r.x = p.x * p.x - p.y * p.y + q.x;" +
"    r.y = 2.0 * p.x * p.y + q.y;" +
"    p.x = r.x;" +
"    p.y = r.y;" +
"    h -= 1.0 / 64.0;" +
"    if(length(p) > bound){ outFlag = true; break; }" +
"  }" +
"  if(outFlag){" +
"    return getRGB(h, 1.0, 1.0);" +
"  }" +
"  return vec3(0.2 + 0.1 * cos(u_count * pi / 480.0));" +
"}" +
"void main(void){" +
"  vec2 p = (gl_FragCoord.xy - u_resolution.xy) * 1.0 / u_resolution.xy;" + // ±2の範囲に正規化
"  vec3 col = getJS(p);" +
"  gl_FragColor = vec4(col, 1.0);" +
"}";

let gr;
let properFrameCount = 0;

function setup(){
  createCanvas(SIZE, SIZE2);
  gr = createGraphics(SIZE, SIZE2, WEBGL);
  myShader = gr.createShader(vs, fs);
  gr.shader(myShader);
  frameRate(30);
}

function draw(){
  background(0);
  myShader.setUniform("u_resolution", [SIZE, SIZE2]);
  myShader.setUniform("u_mouse", [constrain((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, SIZE), constrain((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, SIZE2)]);
  myShader.setUniform("u_count", properFrameCount % 960);
  gr.quad(-1, -1, -1, 1, 1, 1, 1, -1);
  image(gr, 0, 0);
  //noLoop();
  properFrameCount++;
}

let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save('pix.jpg');
    lapse = millis();
  }
}

